    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We reviewed relevant internet sources from the WHO library database and Google Scholar for additional gray literature.",
      "reason": "The authors name the internet sources (WHO library database and Google Scholar) but do not provide the URLs for these sources."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "To supplement the search, we also reviewed reports published by agencies, including the WHO, UNICEF, and the World Bank.",
      "reason": "The authors explicitly name the organizations (WHO, UNICEF, and the World Bank) whose reports were reviewed."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention contacting individuals to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Finally, we identified additional studies using the snowball method by reviewing the reference lists of the retrieved articles.",
      "reason": "The authors specify that they reviewed the reference lists of the retrieved articles."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Again, we conducted a further snowballing search through hand-searching or by searching for references from the initially identified studies.",
      "reason": "The authors describe using snowballing/reference searching, which constitutes backward citation searching."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report consulting specific journals or conference proceedings as a distinct search source."
    }
  ],
  "confidence": 100
}

